package authn_test

import (
	"crypto/ed25519"
	"crypto/rand"
	"testing"

	"github.com/egdaemon/eg/authn"
	"github.com/egdaemon/eg/internal/jwtx"
	"github.com/gofrs/uuid/v5"
	"github.com/stretchr/testify/require"
	"golang.org/x/crypto/ssh"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestAutoTokenState(t *testing.T) {
	t.Run("encodes a valid state with uuid and public key", func(t *testing.T) {
		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		encoded, err := authn.AutoTokenState(signer)
		require.NoError(t, err)
		require.NotEmpty(t, encoded)

		var decoded struct {
			ID        string `json:"id"`
			PublicKey []byte `json:"pkey"`
		}
		require.NoError(t, jwtx.DecodeJSON(encoded, &decoded))

		u, err := uuid.FromString(decoded.ID)
		require.NoError(t, err)
		require.Equal(t, uint8(4), u.Version())

		require.Equal(t, signer.PublicKey().Marshal(), decoded.PublicKey)
	})

	t.Run("generates a unique id on each call", func(t *testing.T) {
		_, priv, err := ed25519.GenerateKey(rand.Reader)
		require.NoError(t, err)
		signer, err := ssh.NewSignerFromKey(priv)
		require.NoError(t, err)

		first, err := authn.AutoTokenState(signer)
		require.NoError(t, err)
		second, err := authn.AutoTokenState(signer)
		require.NoError(t, err)

		require.NotEqual(t, first, second)
	})
}
